class Cart {
  constructor() {
    this.items = [];
  }

  addItem(name, price, qty) {
    this.items.push({ name, price, qty });
  }

  total() {
    return this.items.reduce((acc, item) => acc + item.price * item.qty, 0);
  }

  applyDiscount(pct) {
    if (pct < 0 || pct > 100) {
      throw new Error("Discount percentage must be between 0 and 100");
    }
    return this.total() * (1 - pct / 100);
  }
}

module.exports = Cart;

const assert = require('assert');

// Test addItem
const cart = new Cart();
cart.addItem('Apple', 1.0, 2);
assert.strictEqual(cart.items.length, 1);
assert.strictEqual(cart.items[0].name, 'Apple');
assert.strictEqual(cart.items[0].price, 1.0);
assert.strictEqual(cart.items[0].qty, 2);

// Test total
assert.strictEqual(cart.total(), 2.0);

// Test applyDiscount
assert.strictEqual(cart.applyDiscount(10), 1.8);
try {
  cart.applyDiscount(105);
} catch (e) {
  assert.strictEqual(e.message, "Discount percentage must be between 0 and 100");
}

console.log("All tests passed!");

class Queue {
  constructor() {
    this.items = [];
  }

  enqueue(x) {
    this.items.push(x);
  }

  dequeue() {
    if (this.isEmpty()) {
      throw new Error("Queue is empty");
    }
    return this.items.shift();
  }

  size() {
    return this.items.length;
  }

  isEmpty() {
    return this.items.length === 0;
  }
}

module.exports = Queue;

const assert = require('assert');

// Test enqueue
let queue = new Queue();
queue.enqueue(1);
queue.enqueue(2);
assert.strictEqual(queue.size(), 2);

// Test dequeue
assert.strictEqual(queue.dequeue(), 1);
assert.strictEqual(queue.size(), 1);

// Test isEmpty
assert.strictEqual(queue.isEmpty(), false);
queue.dequeue();
assert.strictEqual(queue.isEmpty(), true);

// Test error on dequeue from empty queue
try {
  queue.dequeue();
  assert.fail("Expected an error to be thrown");
} catch (e) {
  assert.strictEqual(e.message, "Queue is empty");
}

console.log("All tests passed!");

